var date = new Date();
var newrelease = date.getFullYear() + "." + date.getMonth() + "." + date.getDate() + "-" + date.getHours() + "." + date.getMinutes() + "." + date.getSeconds()


msg.filename = '/home/pi/Uploads/Updates/Beta/Backup/' + newrelease + '.json'

return msg;

var date = msg.FileDate
var update = global.get('NewNodes');

global.set("Update.Installed", date);
global.set("Update.Version", "BOOKWORM-" + update)
return msg;

if (msg.statusCode === 200) {
    msg.new_node_modules = msg.payload;
    return msg;
}

msg.actual_node_modules = Object.keys(msg.payload.dependencies)

delete msg.payload;
delete msg.headers;
delete msg.statusCode;
delete msg.responseUrl;
delete msg.redirectList;
delete msg.retry;
delete msg.filename;

return msg;

var newNodes = msg.new_node_modules;
var actualNodes = msg.actual_node_modules;

newNodes = newNodes.filter(val => !actualNodes.includes(val));

if (newNodes.length === 0) {
    global.set("NewNodes", msg.update);
    msg.payload = "NoNewNode";
    node.send(msg)
}
else {
    global.set("NewNodes", newNodes.length);
    newNodes.forEach(function (nodes) {
        msg.payload = {
            module: nodes
        }
        node.send(msg);
    });
}

//var NewNodes = flow.get('NewNodes');
var NewNodes = global.get('NewNodes');
NewNodes--;

if (NewNodes === 0) {
    global.set("NewNodes", msg.update);
    msg.payload = "reload";
    return msg;
}

else {
    global.set("NewNodes", NewNodes);
}

var update = global.get('NewNodes');

if (update === "STABLE") {
    return ([msg, null])
}
else if (update === "BETA") {
    return ([null, msg])
}

